//! BERT WordPiece tokenizer, matching HF `tokenizers` for `potion-base-8M`
//! (`BertNormalizer` + `BertPreTokenizer` + `WordPiece`). See contract.md,
//! "Tokenization". Unicode classes come from [`super::unicode_tables`], which
//! was generated by probing HF itself.

use unicode_normalization::UnicodeNormalization;

use super::unicode_tables::{CLEAN_DROP, CLEAN_SPACE, NONSPACING_MARK, PUNCT};
use crate::contract::MAX_TOKEN_IDS;

/// HF `WordPiece.max_input_chars_per_word`.
pub const MAX_WORD_CHARS: usize = 100;
const CONTINUATION: &str = "##";

fn in_table(table: &[(u32, u32)], c: char) -> bool {
    let c = c as u32;
    table
        .binary_search_by(|&(lo, hi)| {
            if hi < c {
                std::cmp::Ordering::Less
            } else if lo > c {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// HF `clean_text` drop set: NUL, U+FFFD, and `C*` other than `\t\n\r`.
pub fn is_clean_drop(c: char) -> bool {
    in_table(CLEAN_DROP, c)
}

/// Unicode `Mn` (as HF sees it).
pub fn is_nonspacing_mark(c: char) -> bool {
    in_table(NONSPACING_MARK, c)
}

fn is_clean_space(c: char) -> bool {
    in_table(CLEAN_SPACE, c)
}

/// BERT punctuation: ASCII punctuation or Unicode `P*`.
pub fn is_punct(c: char) -> bool {
    c.is_ascii_punctuation() || in_table(PUNCT, c)
}

fn is_cjk(c: char) -> bool {
    matches!(c as u32,
        0x4E00..=0x9FFF
        | 0x3400..=0x4DBF
        | 0x20000..=0x2A6DF
        | 0x2A700..=0x2B73F
        | 0x2B740..=0x2B81F
        // HF uses 0x2B920 here (Google BERT: 0x2B820); HF is the ground truth.
        | 0x2B920..=0x2CEAF
        | 0xF900..=0xFAFF
        | 0x2F800..=0x2FA1F)
}

/// `BertNormalizer{clean_text, handle_chinese_chars, strip_accents, lowercase}`
/// in HF's order: clean, CJK spacing, NFD + drop `Mn`, lowercase (per char).
pub fn normalize(text: &str) -> String {
    let mut spaced = String::with_capacity(text.len() + 8);
    for c in text.chars() {
        if is_clean_drop(c) {
            continue;
        }
        let c = if is_clean_space(c) { ' ' } else { c };
        if is_cjk(c) {
            spaced.push(' ');
            spaced.push(c);
            spaced.push(' ');
        } else {
            spaced.push(c);
        }
    }
    let mut out = String::with_capacity(spaced.len());
    for c in spaced.nfd() {
        if in_table(NONSPACING_MARK, c) {
            continue;
        }
        // HF lowercases char by char (no final-sigma context rule).
        out.extend(c.to_lowercase());
    }
    out
}

/// `BertPreTokenizer`: split on whitespace (removed), then isolate punctuation.
pub fn pre_tokenize(normalized: &str) -> Vec<&str> {
    let mut words = Vec::new();
    for piece in normalized.split(char::is_whitespace) {
        let mut start = 0;
        for (i, c) in piece.char_indices() {
            if is_punct(c) {
                if start < i {
                    words.push(&piece[start..i]);
                }
                words.push(&piece[i..i + c.len_utf8()]);
                start = i + c.len_utf8();
            }
        }
        if start < piece.len() {
            words.push(&piece[start..]);
        }
    }
    words
}

/// Token → id lookup. Implemented by the embedded vocab and by test vocabs.
pub trait Vocab {
    fn id(&self, token: &str) -> Option<u32>;
    fn unk_id(&self) -> u32;
    fn is_special(&self, id: u32) -> bool;
}

/// Greedy longest-match-first WordPiece for one pre-token. Pushes `[UNK]` for
/// words over [`MAX_WORD_CHARS`] or with any unmatched piece.
pub fn wordpiece<V: Vocab + ?Sized>(word: &str, vocab: &V, buf: &mut String, out: &mut Vec<u32>) {
    if word.chars().count() > MAX_WORD_CHARS {
        out.push(vocab.unk_id());
        return;
    }
    let mark = out.len();
    let mut start = 0;
    while start < word.len() {
        let mut end = word.len();
        let mut found = None;
        while start < end {
            buf.clear();
            if start > 0 {
                buf.push_str(CONTINUATION);
            }
            buf.push_str(&word[start..end]);
            if let Some(id) = vocab.id(buf) {
                found = Some(id);
                break;
            }
            end -= word[start..end]
                .chars()
                .next_back()
                .map_or(1, char::len_utf8);
        }
        match found {
            Some(id) => {
                out.push(id);
                start = end;
            }
            None => {
                out.truncate(mark);
                out.push(vocab.unk_id());
                return;
            }
        }
    }
}

/// HF `encode(text, add_special_tokens=False).ids` (includes `[UNK]`).
pub fn encode_raw<V: Vocab + ?Sized>(text: &str, vocab: &V) -> Vec<u32> {
    let normalized = normalize(text);
    let mut out = Vec::new();
    let mut buf = String::new();
    for word in pre_tokenize(&normalized) {
        wordpiece(word, vocab, &mut buf, &mut out);
    }
    out
}

/// Contract step 6: drop special ids and keep the first 512.
pub fn encode<V: Vocab + ?Sized>(text: &str, vocab: &V) -> Vec<u32> {
    let mut ids = encode_raw(text, vocab);
    ids.retain(|&id| !vocab.is_special(id));
    ids.truncate(MAX_TOKEN_IDS);
    ids
}

/// The vocabulary embedded by `build.rs` (`vocab.txt` + `vocab_sorted.u32`).
#[cfg(has_model)]
pub struct EmbeddedVocab {
    tokens: Vec<&'static str>,
}

#[cfg(has_model)]
mod embedded {
    include!(concat!(env!("OUT_DIR"), "/model_meta.rs"));
    pub static VOCAB_TXT: &str = include_str!(concat!(env!("OUT_DIR"), "/vocab.txt"));
    pub static VOCAB_SORTED: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/vocab_sorted.u32"));
}

#[cfg(has_model)]
pub use embedded::{DIM as MODEL_DIM, ROWS as MODEL_ROWS};

#[cfg(has_model)]
impl EmbeddedVocab {
    pub fn load() -> Self {
        let tokens: Vec<&'static str> = embedded::VOCAB_TXT.split('\n').collect();
        assert_eq!(tokens.len(), embedded::ROWS, "embedded vocab size");
        EmbeddedVocab { tokens }
    }

    fn sorted(&self, i: usize) -> u32 {
        let b = &embedded::VOCAB_SORTED[i * 4..i * 4 + 4];
        u32::from_le_bytes([b[0], b[1], b[2], b[3]])
    }

    pub fn len(&self) -> usize {
        self.tokens.len()
    }

    pub fn is_empty(&self) -> bool {
        self.tokens.is_empty()
    }

    pub fn token(&self, id: u32) -> Option<&'static str> {
        self.tokens.get(id as usize).copied()
    }
}

#[cfg(has_model)]
impl Vocab for EmbeddedVocab {
    fn id(&self, token: &str) -> Option<u32> {
        let key = token.as_bytes();
        let (mut lo, mut hi) = (0usize, self.tokens.len());
        while lo < hi {
            let mid = (lo + hi) / 2;
            let id = self.sorted(mid);
            match self.tokens[id as usize].as_bytes().cmp(key) {
                std::cmp::Ordering::Less => lo = mid + 1,
                std::cmp::Ordering::Greater => hi = mid,
                std::cmp::Ordering::Equal => return Some(id),
            }
        }
        None
    }

    fn unk_id(&self) -> u32 {
        embedded::UNK_ID
    }

    fn is_special(&self, id: u32) -> bool {
        embedded::SPECIAL_IDS.contains(&id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    struct Toy(HashMap<&'static str, u32>);

    impl Toy {
        fn new() -> Self {
            let toks = [
                "[PAD]", "[UNK]", "[CLS]", "[SEP]", "[MASK]", "hello", "world", "un", "##aff",
                "##able", "cafe", ",", "!", "中", "国", "a", "##b", "?",
            ];
            Toy(toks
                .iter()
                .enumerate()
                .map(|(i, t)| (*t, i as u32))
                .collect())
        }
    }

    impl Vocab for Toy {
        fn id(&self, t: &str) -> Option<u32> {
            self.0.get(t).copied()
        }
        fn unk_id(&self) -> u32 {
            1
        }
        fn is_special(&self, id: u32) -> bool {
            id <= 4
        }
    }

    #[test]
    fn normalizes_accents_case_and_controls() {
        assert_eq!(normalize("Café\u{200B}\tÉTÉ"), "cafe ete");
        assert_eq!(normalize("ΣΑΣ"), "σασ");
        assert_eq!(normalize("a\u{0}b\u{FFFD}c"), "abc");
    }

    #[test]
    fn spaces_cjk() {
        assert_eq!(normalize("中国x"), " 中  国 x");
        assert_eq!(pre_tokenize(&normalize("中国x")), vec!["中", "国", "x"]);
    }

    #[test]
    fn isolates_punctuation() {
        assert_eq!(
            pre_tokenize("hello,world!  a-b"),
            vec!["hello", ",", "world", "!", "a", "-", "b"]
        );
    }

    #[test]
    fn continuation_pieces() {
        let v = Toy::new();
        assert_eq!(encode("unaffable", &v), vec![7, 8, 9]);
        assert_eq!(encode("ab", &v), vec![15, 16]);
    }

    #[test]
    fn unknown_and_long_words_are_dropped() {
        let v = Toy::new();
        assert_eq!(encode_raw("hello zzz", &v), vec![5, 1]);
        assert_eq!(encode("hello zzz", &v), vec![5]);
        let long = "a".to_string() + &"b".repeat(100);
        assert_eq!(long.chars().count(), 101);
        assert_eq!(encode_raw(&long, &v), vec![1]);
        let ok = "a".to_string() + &"b".repeat(99);
        assert_eq!(encode_raw(&ok, &v).len(), 100);
    }

    #[test]
    fn caps_at_512_ids() {
        let v = Toy::new();
        assert_eq!(encode(&"hello ".repeat(600), &v).len(), MAX_TOKEN_IDS);
    }
}
